-- 中国多商家校园外卖 MVP（MySQL 8.0+）
CREATE DATABASE IF NOT EXISTS campus_food_delivery DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campus_food_delivery;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, openid VARCHAR(64) UNIQUE NULL, nickname VARCHAR(64) NOT NULL, phone VARCHAR(20) NULL, role ENUM('STUDENT','MERCHANT','ADMIN') NOT NULL DEFAULT 'STUDENT', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchants (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_user_id BIGINT NULL, name VARCHAR(100) NOT NULL, category VARCHAR(50) NOT NULL, notice VARCHAR(255) NULL, business_status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN', min_order_amount DECIMAL(10,2) NOT NULL DEFAULT 0, delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT, merchant_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(500) NULL, price DECIMAL(10,2) NOT NULL, image_url VARCHAR(500) NULL, monthly_sales INT NOT NULL DEFAULT 0, status ENUM('ON_SALE','OFF_SALE') NOT NULL DEFAULT 'ON_SALE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(merchant_id) REFERENCES merchants(id), INDEX idx_product_merchant_status(merchant_id,status));
CREATE TABLE addresses (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, contact_name VARCHAR(50) NOT NULL, phone VARCHAR(20) NOT NULL, campus VARCHAR(100) NOT NULL, building VARCHAR(100) NOT NULL, detail VARCHAR(255) NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(32) NOT NULL UNIQUE, user_id BIGINT NOT NULL, merchant_id BIGINT NOT NULL, address_id BIGINT NOT NULL, status ENUM('PENDING','ACCEPTED','REJECTED','PREPARING','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING', goods_amount DECIMAL(10,2) NOT NULL, delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0, total_amount DECIMAL(10,2) NOT NULL, remark VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(merchant_id) REFERENCES merchants(id), FOREIGN KEY(address_id) REFERENCES addresses(id), INDEX idx_order_user(user_id,created_at), INDEX idx_order_merchant(merchant_id,status,created_at));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NULL, product_name VARCHAR(100) NOT NULL, product_price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
